 setLandmarkLayer(layer,on){this.landmarkLayers??=new Set(['building','master','geography','history']);if(on)this.landmarkLayers.add(layer);else this.landmarkLayers.delete(layer);this.refreshLandmarks();this.refreshBridges();},
