 updateLabels(selected,stamps=[]){this.selected=selected;this.refreshBridges();this.refreshLandmarks();if(this.gpu){if(this.selectionRing){this.mapGroup.remove(this.selectionRing);this.selectionRing.geometry.dispose();this.selectionRing.material.dispose();}const p=this.globe.placements.get(selected),ring=new THREE.Mesh(new THREE.TorusGeometry(.85,.045,5,40),new THREE.MeshBasicMaterial({color:'#fff3b2'}));ring.position.copy(topPoint(p,this.globe.radius,.06));ring.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),V(p.center));this.selectionRing=ring;this.mapGroup.add(ring);ring.visible=this.landmarkLayers.has('building');}for(const b of this.labels.children){b.classList.toggle('selected',+b.dataset.id===selected);b.classList.toggle('completed',stamps.includes(+b.dataset.id));b.setAttribute('aria-pressed',String(+b.dataset.id===selected));}this.mapDirty=true;},
 routeInfo(edge){this.routeCache??=new Map();const id=typeof edge==='string'?edge:edge.id;const e=typeof edge==='string'?this.relationships.find(x=>x.id===edge):edge;if(!e)return null;if(!this.routeCache.has(id))this.routeCache.set(id,routeForEdge(e,this.globe.masterPlacements));return this.routeCache.get(id);},
 addRelationshipBridges(){this.bridgeGroups=[];for(const e of this.relationships){const route=this.routeInfo(e),g=new THREE.Group();g.add(routeMesh(route.points,e.type,route.mode));const token=transportMarker(route.mode,'#fff2c6');g.add(token);g.userData={edge:e.id,route,token};this.bridgeGroups.push(g);this.mapGroup.add(g);}this.associationGroups=[];for(const a of this.globe.associations){const route=associationRoute(a,this.globe),g=routeMesh(route.points,'geography','association');g.userData={association:a,route};this.associationGroups.push(g);this.mapGroup.add(g);}this.updateRouteMarkers(0);},
 updateRouteMarkers(time){if(!this.bridgeGroups)return;for(const g of this.bridgeGroups){const {route,token}=g.userData,points=route.points,phase=this.reduced?.5:(time*.035+this.relationships.findIndex(e=>e.id===g.userData.edge)*.17)%1,index=Math.min(points.length-2,Math.floor(phase*(points.length-1))),t=phase*(points.length-1)-index,p=V(points[index]).lerp(V(points[index+1]),t);token.position.copy(p);const up=p.clone().normalize(),forward=V(points[index+1]).sub(V(points[index])).normalize(),right=up.clone().cross(forward).normalize();forward.crossVectors(right,up).normalize();token.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(right,up,forward));token.visible=route.mode!=='local'&&this.mapOrbit.scale<.75&&g.visible;}},
 refreshBridges(){const ids=new Set(this.visibleEdges().map(e=>e.id));for(const g of this.bridgeGroups||[])g.visible=ids.has(g.userData.edge);for(const g of this.associationGroups||[])g.visible=(this.landmarkLayers?.has('geography')??true)&&(this.edgeScope==='all'||g.userData.association.architectId===this.selected);this.mapDirty=true;},
