   if(this.landmarkLayers.has('geography'))for(const a of this.globe.associations){if(this.edgeScope==='selected'&&a.architectId!==this.selected)continue;const route=associationRoute(a,this.globe),d=this.projectedRoute(route);if(d)svg+=`<g class="connection-hit geography" role="button" tabindex="0" data-geography="${a.architectId}" aria-label="作品與執業基地跨國定位，查看來源"><path d="${d}" fill="none" stroke="#67dce5" stroke-width="2" stroke-dasharray="9 4 2 4" opacity=".8"/><path d="${d}" fill="none" stroke="transparent" stroke-width="12" class="edge-target"/></g>`;}
